def content():
    faqs=[dict(id=f"{audience}-{i+1}",audience=audience,topic=topic,question=value[0],answer=value[1])
          for audience,topics in (("consumer",CONSUMER),("operator",OPERATOR),("special",SPECIAL))
          for i,(topic,value) in enumerate(topics.items())]
    body=dict(faqs=faqs,guides=GUIDES,policies=POLICIES,publication="development_review",live_operations_approved=False)
    body["version"]=hashlib.sha256(json.dumps(body,ensure_ascii=False,sort_keys=True).encode()).hexdigest()
    return body
